        #            "bondContract": [
        #                {
        #                    "o": 15960430,
        #                    "u": null,
        #                    "p": 62614,
        #                    "i": "US-T",
        #                    "rr": 0,
        #                    "ctl": null,
        #                    "t": null,
        #                    "d": null,
        #                    "cb": null,
        #                    "pset": null,
        #                    "hb": [
        #                        {
        #                            "n": "TSRYS4493816",
        #                            "c": null,
        #                            "b": null,
        #                            "r": null,
        #                            "l": null,
        #                            "mc": null,
        #                            "mt": 1000,
        #                            "p": null,
        #                            "e": null,
        #                            "mx": 1000,
        #                            "quotingConvention": 1,
        #                            "cleanOrDirty": "C"
        #                        },
        #                        {
        #                            "n": "T 6 1/2 11/15/26",
        #                            "c": null,
        #                            "b": null,
        #                            "r": null,
        #                            "l": null,
        #                            "mc": null,
        #                            "mt": 1000,
        #                            "p": null,
