    def parse_last_price(self, entry: dict, market: Market = None) -> LastPrice:
        marketId = self.safe_string(entry, 'conid')
        resolved = self.safe_market(marketId, market)
        timestamp = self.safe_integer(entry, '_updated')
        return {
            'symbol': resolved['symbol'],
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'price': self.parse_number(self.ibkr_parse_value(self.safe_string(entry, '31'))),
            'side': None,
            'info': entry,
        }

