    async def fetch_open_interests(self, symbols: Strings = None, params: dict = {}) -> OpenInterests:
        """
        retrieves the open interest of multiple futures or swap markets

        https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-market-data/get-md-snapshot

        :param str[] symbols: unified symbols of the markets to fetch the open interest for
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a dictionary of `open interest structures <https://docs.ccxt.com/?id=open-interest-structure>`
        """
        if symbols is None:
            raise ArgumentsRequired(self.id + ' fetchOpenInterests() requires a symbols argument')
        await self.authenticate()
        if self.markets is None:
            await self.load_markets()
        symbolsNormalized = self.market_symbols(symbols)
        for i in range(0, len(symbolsNormalized)):
            market = self.market(symbolsNormalized[i])
            if not market['contract']:
                raise BadRequest(self.id + ' fetchOpenInterests() supports contract markets only, ' + market['symbol'] + ' is not a contract market')
        # 7697 futures open interest, 7638 option open interest, 31 last price for the open interest value
        response = await self.ibkr_fetch_snapshot(symbolsNormalized, '31,7697,7638', ['7697', '7638'], params)
        #
        #     [ { "31": "82838.50", "7697": "12345", "conidEx": "770561201", "_updated": 1791449398940, "conid": 770561201 } ]
        #
        return self.parse_open_interests(self.to_array(response), symbolsNormalized)

    def parse_open_interest(self, interest: dict, market: Market = None) -> OpenInterest:
        marketId = self.safe_string(interest, 'conid')
        resolved = self.safe_market(marketId, market)
        timestamp = self.safe_integer(interest, '_updated')
        openInterest = self.ibkr_parse_value(self.safe_string_2(interest, '7697', '7638'))
        last = self.ibkr_parse_value(self.safe_string(interest, '31'))
        contractSize = self.safe_string(resolved, 'contractSize')
        openInterestValue = None
        if (openInterest is not None) and (last is not None) and (contractSize is not None):
            openInterestValue = Precise.string_mul(Precise.string_mul(openInterest, contractSize), last)
        return self.safe_open_interest({
            'symbol': resolved['symbol'],
            'openInterestAmount': self.parse_number(openInterest),
            'openInterestValue': self.parse_number(openInterestValue),
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'info': interest,
        }, resolved)

    async def fetch_status(self, params: dict = {}) -> Status:
        """
        the status of the brokerage session, 'ok' when authenticated and connected

        https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/get-brokerage-status

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a `status structure <https://docs.ccxt.com/?id=exchange-status-structure>`
        """
        await self.authenticate()
        response = await self.webapiPostV1ApiIserverAuthStatus(params)
        #
        #     {
        #         "authenticated": true,
        #         "competing": false,
        #         "connected": true,
        #         "message": "",
        #         "MAC": "12:B:B3:23:BF:A0",
        #         "serverInfo": { "serverName": "JifN19053", "serverVersion": "Build 10.25.0p, Dec 5, 2023 5:48:12 PM" },
        #         "fail": ""
        #     }
        #
        authenticated = self.safe_bool(response, 'authenticated', False)
        connected = self.safe_bool(response, 'connected', False)
        status = 'ok' if (authenticated and connected) else 'error'
        return {
            'status': status,
            'updated': None,
            'eta': None,
            'url': None,
            'info': response,
        }

    def ibkr_parse_value(self, value: Str) -> Str:
        # snapshot values are formatted strings: "C82838.50" (prior close), "H1.2" (halted), "+1.04", "1.5%", "1M", "1,234", "$11,000K" (bond sizes, the principal amount)
        if (value is None) or (value == '') or (value == 'N/A'):
            return None
        valueParts = value.split(',')
        result = ''.join(valueParts)
        if result.startswith('C') or result.startswith('H') or result.startswith('+') or result.startswith('$'):
            result = result[1:]
        if result.endswith('%'):
            result = result[0:len(result) - 1]
        multiplier = None
        if result.endswith('K'):
            multiplier = '1000'
        elif result.endswith('M'):
            multiplier = '1000000'
        elif result.endswith('B'):
            multiplier = '1000000000'
        if multiplier is not None:
            return Precise.string_mul(result[0:len(result) - 1], multiplier)
        if result == '':
            return None
        return result

    def parse_ticker(self, ticker: dict, market: Market = None) -> Ticker:
        marketId = self.safe_string(ticker, 'conid')
        resolved = self.safe_market(marketId, market)
        timestamp = self.safe_integer(ticker, '_updated')
        last = self.ibkr_parse_value(self.safe_string(ticker, '7296'))  # 31 might contain symbol
        if last is None:
            # if precise fields are not provided, use generic "last price" field
            last = self.ibkr_parse_value(self.safe_string(ticker, '31'))
        return self.safe_ticker({
            'symbol': resolved['symbol'],
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'high': self.ibkr_parse_value(self.safe_string(ticker, '70')),
            'low': self.ibkr_parse_value(self.safe_string(ticker, '71')),
            'bid': self.ibkr_parse_value(self.safe_string(ticker, '84')),
            'bidVolume': self.ibkr_parse_value(self.safe_string(ticker, '88')),
            'ask': self.ibkr_parse_value(self.safe_string(ticker, '86')),
            'askVolume': self.ibkr_parse_value(self.safe_string(ticker, '85')),
            'vwap': None,
            'open': self.ibkr_parse_value(self.safe_string(ticker, '7295')),
            'close': last,
            'last': last,
            'previousClose': self.ibkr_parse_value(self.safe_string(ticker, '7741')),
            'change': self.ibkr_parse_value(self.safe_string(ticker, '82')),
            'percentage': self.ibkr_parse_value(self.safe_string(ticker, '83')),
            'average': None,
            'baseVolume': self.ibkr_parse_value(self.safe_string(ticker, '7762')),
            'quoteVolume': None,
            'markPrice': self.ibkr_parse_value(self.safe_string(ticker, '7635')),
            'indexPrice': None,
            'info': ticker,
        }, resolved)

    async def fetch_ohlcv(self, symbol: str, timeframe: str = '1m', since: Int = None, limit: Int = None, params: dict = {}) -> list[list]:
        """
        fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market

        https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-market-data/get-md-history

        :param str symbol: unified symbol of the market to fetch OHLCV data for
        :param str timeframe: the length of time each candle represents
        :param int [since]: timestamp in ms of the earliest candle to fetch
        :param int [limit]: the maximum amount of candles to fetch, max 1000
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param boolean [params.outsideRth]: include data outside regular trading hours
        :param str [params.source]: 'Last', 'Bid_Ask' or 'Midpoint'
        :returns int[][]: A list of candles ordered as timestamp, open, high, low, close, volume
        """
        await self.authenticate()
        if self.markets is None:
            await self.load_markets()
        market = self.market(symbol)
        maxLimit = 1000
        configuredLimit = self.safe_integer(self.safe_dict(self.options, 'fetchOHLCV', {}), 'limit')
        if configuredLimit is not None:
            maxLimit = configuredLimit
        requestLimit = maxLimit
        if limit is not None:
            requestLimit = min(limit, maxLimit)
        duration = self.parse_timeframe(timeframe)
        request = {
            'conid': market['id'],
            'bar': self.safe_string(self.timeframes, timeframe, timeframe),
        }
        if since is not None:
            # startTime is exclusive, the first returned bar opens strictly after it, so the request starts one bar earlier
            # and the extra leading bar is removed by filterBySinceLimit in parseOHLCVs
            request['startTime'] = self.ibkr_format_time(since - duration * 1000)
            request['direction'] = '1'  # forward from startTime, by default startTime is the end of the range
            if limit is not None:
                if limit < maxLimit:
                    requestLimit = limit + 1
        request['period'] = self.ibkr_period(duration, requestLimit)
        response = await self.webapiGetV1ApiIserverMarketdataHistory(self.extend(request, params))
        #
        #     {
        #         "points": 99,
        #         "startTime": "20261007-18:20:00",
        #         "data": [
        #             { "o": 336.94, "c": 336.89, "h": 336.97, "l": 336.85, "v": 1164.625, "t": 1791397200000 }
        #         ],
        #         ...
        #     }
        #
        data = self.safe_list(response, 'data', [])
        return self.parse_ohlcvs(data, market, timeframe, since, limit)

    def ibkr_period(self, duration: int, limit: int) -> str:
        # duration of one bar in seconds, the period is expressed in the largest fitting unit
        total = duration * limit
        if duration < 3600:
            return self.number_to_string(self.parse_to_int(total / 60)) + 'min'
        elif duration < 86400:
            return self.number_to_string(self.parse_to_int(total / 3600)) + 'h'
        elif duration < 604800:
            return self.number_to_string(self.parse_to_int(total / 86400)) + 'd'
        elif duration < 2592000:
            return self.number_to_string(self.parse_to_int(total / 604800)) + 'w'
        # monthly bars, long month periods (e.g. "1000m") are rejected with "Chart data unavailable", so they are expressed in years
        months = self.parse_to_int(total / 2592000)
        if months <= 12:
            return self.number_to_string(months) + 'm'
        years = min(self.parse_to_int((months + 11) / 12), 15)  # 15y is the documented maximum period
        return self.number_to_string(years) + 'y'

    def ibkr_format_time(self, timestamp: int) -> str:
        # YYYYMMDD-hh:mm:ss in UTC
        iso = self.iso8601(timestamp)
        return self.yyyymmdd(timestamp, '') + '-' + iso[11:19]

    def parse_ohlcv(self, ohlcv: object, market: Market = None) -> list:
        return [
            self.safe_integer(ohlcv, 't'),
            self.safe_number(ohlcv, 'o'),
            self.safe_number(ohlcv, 'h'),
            self.safe_number(ohlcv, 'l'),
            self.safe_number(ohlcv, 'c'),
            self.safe_number(ohlcv, 'v'),
        ]

    async def fetch_accounts(self, params: dict = {}) -> list[Account]:
        """
        fetch all the accounts associated with a profile

        https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio/get-all-accounts

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.method]: 'privateGetPortfolioAccounts'(default) or 'privateGetPortfolioSubaccounts'
        :returns dict[]: a list of `account structures <https://docs.ccxt.com/?id=account-structure>`
        """
        # as required by IBKR, iserver/accounts must be called at least once before any other trading endpoint
        portfolioAccounts = await self.fetch_portfolio_accounts(params)
        accountsById = self.index_by(portfolioAccounts, 'accountId')
        accountIds = list(accountsById.keys())
        length = len(accountIds)
        if length == 0:
            raise ExchangeError('No tradingaccount IDs found for the user')
        if self.safe_string(self.options, 'accountId') is None:
            if length == 1:
                self.options['accountId'] = accountIds[0]
            else:
                raise ExchangeError('Multiple account IDs found, please set .options["accountId"] to desired one from: ' + ', '.join(accountIds))
        accounts = []
        for i in range(0, len(portfolioAccounts)):
            accounts.append(self.parse_account(self.extend({}, portfolioAccounts[i])))
        return accounts

