    async def create_order(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num = None, params: dict = {}) -> Order:
        """
        create a trade order, order reply prompts are confirmed automatically when options.createOrder.autoConfirmOrderReplies is True

        https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/submit-new-order
        https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/confirm-order-reply

        :param str symbol: unified symbol of the market to create an order in
        :param str type: 'market' or 'limit'
        :param str side: 'buy' or 'sell'
        :param float amount: how much of currency you want to trade in units of base currency
        :param float [price]: the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param float [params.triggerPrice]: the stop price, creates a STP(market) or STP LMT(limit) order
        :param float [params.trailingAmount]: the trailing offset in quote currency, creates a TRAIL or TRAILLMT order
        :param float [params.trailingPercent]: the trailing offset in percent, creates a TRAIL or TRAILLMT order
        :param str [params.timeInForce]: 'DAY', 'IOC', 'GTC', 'OPG' or 'PAX'
        :param str [params.clientOrderId]: a unique id for the order, sent as cOID
        :param boolean [params.outsideRTH]: allow the order to execute outside regular trading hours
        :param str [params.accountId]: the account id, defaults to options["accountId"]
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        await self.authenticate()
        if self.markets is None:
            await self.load_markets()
        market = self.market(symbol)
        accountId, paramsWithoutAccoundId = await self.load_account_id(params)
        orderRequest = self.create_order_request(symbol, type, side, amount, price, paramsWithoutAccoundId)
        orderRequest['acctId'] = accountId
        request = {
            'accountId': accountId,
            'orders': [orderRequest],
        }
        response = await self.webapiPostV1ApiIserverAccountAccountIdOrders(request)
        result = await self.ibkr_handle_order_replies(response, 'createOrder')
        #
        #     [ { "order_id": "1370093239", "order_status": "PreSubmitted", "encrypt_message": "1" } ]
        #
        return self.parse_order(result, market)

